<script setup>import{computed}from'vue';const p=defineProps({variant:{default:'banner'},pending:{default:0}});defineEmits(['retry']);const text=computed(()=>p.pending?`${p.pending} ${p.pending===1?'registro se sincronizará':'registros se sincronizarán'} al volver la conexión.`:'Sin conexión. Puedes seguir registrando; se guardará en tu dispositivo.')</script><template><component :is="variant==='banner'?'div':'section'" class="offline" :class="`offline--${variant}`" role="status"><i/><div><h2 v-if="variant==='full'">Sin conexión</h2><p>{{text}}</p></div><button @click="$emit('retry')">Reintentar</button></component></template><style scoped>.offline{display:flex;align-items:center;gap:10px;padding:10px 14px;border:1px solid color-mix(in srgb,var(--status-warning) 34%,transparent);border-radius:var(--radius-md);background:color-mix(in srgb,var(--status-warning) 12%,transparent);font-family:var(--font-core)}.offline>i{width:8px;height:8px;border-radius:50%;background:var(--status-warning)}.offline div{flex:1}.offline p{color:var(--text-secondary);font-size:13px}.offline h2{color:var(--text-primary)}button{border:0;background:transparent;color:var(--status-warning);font-weight:600}.offline--full{flex-direction:column;padding:32px;text-align:center;background:transparent;border:0}</style>
